    [5] = {s = {["|1"] = "Speak to Ronan to activate quest.", ["|2"] = "This quest will not show up in Chronicle if you're using it to track quests, however after you talk to Ronan and he mentions that you gave", ["|3"] = "Obtain 3 Shell Bugs from Quadavs or the Auction House, and trade them to Ronan.", ["|4"] = "Zone out (leave the area) and back in again, then speak to Ronan to complete quest."}},
