    [10] = {s = {["|1"] = "Speak with Horatius inside of the Trader's Home at (I-9) in Bastok Markets, who sends you to Dangruf Wadi.", ["|2"] = "Inside Dangruf Wadi, head to the (I-5)/(J-5) boundary, where you'll find a ??? during sunny weather.", ["|3"] = "Head back to Horatius for your reward of 400g."}},
