    [12] = {s = {["|1"] = "Speak to Salimah to begin quest.", ["|2"] = "Obtain any of the following item and trade it to her depending on time of day.", ["|7"] = "All 3 items may be farmed (Sleepshroom from Funguar type, Treant Bulb from Sapling type and Wild Onion from Goblin Thugs or by gardening)", ["|8"] = "Important Note: This quest is repeatable as many times as you want but requires zoning between each trade."}},
    [13] = {s = {["|1"] = "Speak to Michea to start quest", ["|10"] = "Trade the Ingot to Michea to complete the quest.", ["|11"] = "May be repeated by zoning out of the area.", ["|2"] = "Obtain a Copper Ingot from either the Auction House, Goldsmithing guild shops or by crafting it."}},
    [14] = {s = {["|1"] = "Talk to Aquillina in Bastok Markets at (K-9), she will ask for Flint Stones", ["|2"] = "Trade Flint Stone x4 to Aquillina to complete quest.", ["|3"] = "Tip: If you're looking to gain Bastok fame fast, skip this one and work on the other repeatables and also Selbina quests."}},
    [15] = {s = {["|1"] = "Speak to Hungry Wolf inside the Craftmen's Eatery to start the quest.", ["|2"] = "Obtain a Giant Sheep Meat from the Auction House or from Ornery Sheep in South Gustaberg (or elsewhere.)", ["|3"] = "Travel to South Gustaberg (K-9) to find a Goblin campfire (???).", ["|4"] = "Trade the Giant Sheep Meat to the campfire and to begin to cook it.", ["|5"] = "Wait for a minute (Earth time).", ["|6"] = "After the required wait time, check the campfire again to receive a Galkan Sausage.", ["|7"] = "Trade the Galkan Sausage to Hungry Wolf to complete the quest."}},
    [16] = {s = {["|1"] = "Speak to Arawn to start quest.", ["|10"] = "Speak to Arawn again once you have collected all the stamps to complete the quest.", ["|2"] = "Speak to the following 7 guards to obtain the stamps:"}},
    [17] = {s = {["|1"] = "Talk to Qiji, who wants to give his wife, Romilda, a Brass Hairpin.", ["|2"] = "Brass hairpins can be bought off auction houses, or by crafting one.", ["|3"] = "Trade the hairpin to Romilda, who is standing next to Qiji.", ["|4"] = "Talk to Qiji to obtain your reward."}},
    [18] = {s = {["|1"] = "You must have zoned once after finishing Forever to Hold to receive this quest.", ["|2"] = "Talk to Romilda, who wants to give her husband, Qiji, a pair of Cotton Gloves.", ["|3"] = "Once you've got it, trade them to Romilda to finish the quest."}},
    [19] = {s = {["|1"] = "Talk to Pavvke, who asks of you to bring back name tags.", ["|2"] = "Silver Name Tags can be bought off auction houses.", ["|3"] = "Since the tags are rare, you can only turn one in at a time.", ["|4"] = "Trade it to him for your reward."}},
    [20] = {s = {["|1"] = "Obtain a Mythril Sallet from the auction house (Armor > Head) or for 437 Sparks.", ["|2"] = "Speak to Detzo to begin quest.", ["|3"] = "Trade Sallet to Detzo to complete quest and receive your reward."}},
    [21] = {s = {["|1"] = "Speak to Nbu Latteh on Gold Street to start quest.", ["|2"] = "(Optional) speak to Nbu Latteh again, as well as the guard Parnika to the south, for hints at Nbu's occupation.", ["|3"] = "Obtain a Copper Ring either via Auction House, Merchants or Crafting.", ["|4"] = "Trade Copper Ring to Roh Latteh in Bastok Mines (H-7), she is located on the first floor house on Ore Street.", ["|5"] = "Upon NPC dialogue completion, you will obtain Letter from Roh Latteh.", ["|6"] = "If you 'check' the letter (as in read it from your Key Item menu) you will receive a penalty and get only half the actual reward.", ["|7"] = "Return to Nbu Latteh to complete quest.", ["|8"] = "This quest is repeatable for players below Bastok fame level 2."}},
    [22] = {s = {["|1"] = "Speak to Nbu Latteh at (J-9) to begin quest.", ["|2"] = "(Optional) speak to Nbu Latteh again, as well as the guard Parnika to the south, for hints at Nbu's occupation.", ["|3"] = "Travel to Konschtat Highlands and inspect the Signpost at the south edge of G-4 / north edge of G-5.", ["|4"] = "You will receive a Painting of a windmill", ["|5"] = "Return to Bastok Mines and speak to Roh Latteh at (H-7) to complete the quest."}},
    [23] = {s = {["|3"] = "Speak with Evi again.", ["|4"] = "Travel to Konschtat Highlands and look for a ??? near a windmill around the (G-8) square.", ["|5"] = "Touch the ??? to receive a Temporary Key Items: Tattered mission orders", ["|6"] = "Return to Evi, speak with him to complete the quest."}},
    [24] = {s = {["|1"] = "Speak with Baldric inside the Darksteel Forge on the first floor to begin the quest.", ["|2"] = "Obtain a Valkurm Sunsand either via Auction House or by travelling to Valkurm Dunes.", ["|3"] = "Return to Baldric and trade him the sunsand to complete quest."}},
    [25] = {s = {["|1"] = "Talk to Unlucky Rat located on the first floor in the Cermet Refinery, who is having a machine problem.", ["|2"] = "Although he doesn't ask for help, bring him a Slime Oil to alleviate his problem, and to obtain your reward."}},
    [26] = {s = {["|1"] = "Speak to Cid to begin the Quest.", ["|2"] = "Travel to Port Bastok (Home Point #3) and visit the Steaming Sheep Restaurant.", ["|3"] = "Locate Hilda at (E-6) and speak with her.", ["|4"] = "Obtain a Rolanberry 874 in one of two ways:", ["|5"] = "Trade the Rolanberry 874 to Hilda and to receive Unfinished letter.", ["|6"] = "Return to Cid and speak with him to complete the Quest."}},
    [27] = {s = {["|1"] = "Speak to Hilda to begin the quest.", ["|2"] = "Trade a King Truffle to Hilda to receive the Steaming Sheep invitation.", ["|3"] = "Travel to the Metalworks and speak with Raibaht at G-8 (Cid's Lab).", ["|4"] = "Return to the Steaming Sheep restaurant, and speak with Hilda to complete the quest."}},
    [28] = {s = {["|1"] = "Teleport to Bastok Mines Home Point #3, go inside the house (upper floor) at (J-7) and speak with Gumbah.", ["|2"] = "Speak to him repeatedly until you get the cutscene that begins the Quest.", ["|3"] = "Travel to the Palborough Mines and go to the top floor (Map 3).", ["|4"] = "Go to the Boat Docks at (H-8), climb aboard one of the boats, and then interact with the Dock Lever for a cutscene with Zeid.", ["|7"] = "Upon the completion of the mass slaying, proceed to Beadeaux."}},
    [29] = {s = {["|1"] = "Obtain a Silver Ingot from Auction House or by Crafting", ["|2"] = "Speak to Michea to start quest.", ["|3"] = "When the cutscene ends, trade her the Ingot to complete quest."}},
    [30] = {s = {["|1"] = "Obtain a Cinnamon from the Auction House or if you have the Kazham Airship Pass, travel to the port shop in Kazham and purchase it from the", ["|2"] = "Speak with Gwill to begin quest.", ["|3"] = "When cutscene ends, trade him the Cinnamon to complete quest."}},
    [31] = {s = {["|1"] = "Speak with Black Mud to begin quest.", ["|2"] = "Otherwise, travel to Dangruf Wadi and head north from the entrance.", ["|3"] = "Once inside Dangruf Wadi, travel to (I-8) and go up the geyser by standing on top of it until being shot up the ledge.", ["|4"] = "Head northeast to (J-3) and go up a second geyser.", ["|5"] = "Continue following this path to zone out into North Gustaberg", ["|6"] = "Travel east and cross the bridge.", ["|7"] = "Continue following the river towards the base of the waterfall.", ["|8"] = "Locate the Waterfall Base and trade the Brass Canteen to it to receive Drachenfall Water.", ["|9"] = "Return to Bastok and trade the Drachenfall Water to Black Mud to complete the quest."}},
    [32] = {s = {["|1"] = "Speak to Goraow (I-6) in the upper stairway of Ore Street to begin quest.", ["|2"] = "Obtain a Quadav Helm.", ["|3"] = "Trade a Quadav Helm to Goraow to complete the quest.", ["|4"] = "Can be repeated without zoning."}},
    [33] = {s = {["|1"] = "Speak to High Bear to begin quest.", ["|2"] = "Travel to Beadeaux.", ["|3"] = "Upon entry, Proceed straight in, then turn left (go north) when you reach the wall at F-7.", ["|4"] = "From here head south and you'll find yourself going into a cave that leads down.", ["|5"] = "From here, go west and south as you can until you come to the tunnel at F-8 that leads back to the surface; you will pass one Afflictor", ["|6"] = "Follow the surface path along, south past the Mute at F-9.", ["|7"] = "When the weather is raining, a ??? will appear near the base of the smokestacks.", ["|8"] = "Return to High Bear and speak with him to complete the quest."}},
    [34] = {s = {["|1"] = "Speak with Zon-Fobun to begin quest.", ["|2"] = "Go to Beadeaux and proceed to one of the sets of machines: you need to visit an Afflictor (which Curses whoever comes near it, unless they", ["|3"] = "The first, and easiest, set of machines: Go straight in when entering Beadeaux, then turn left (go north) when you reach the wall at F-7.", ["|4"] = "From here head south and you'll find yourself going into a cave that leads down.", ["|5"] = "Now head back east and then take your first turn north all the way to G-7 where you will find the Mute.", ["|6"] = "Return to Zon-Fobun to complete quest."}},
    [35] = {s = {["|1"] = "Speak to Kurando to begin quest.", ["|2"] = "Travel to Rolanberry Fields and proceed to (K-7).", ["|3"] = "Look for the NM Silk Caterpillar.", ["|4"] = "Upon defeating the NM, you will receive a Silkworm Egg", ["|5"] = "Return to Kurando and trade him the egg to complete quest."}},
    [36] = {s = {["|1"] = "Speak with Benita to begin quest.", ["|2"] = "Speak to Tete at (I-5) of Port Bastok", ["|3"] = "Obtain a Bomb Ash from the Auction House, Tenshodo vendors or Alchemy vendors, or by farming Lanterns/Bomb type mobs.", ["|4"] = "Trade Bomb Ash to Benita to complete quest."}},
    [37] = {s = {["|1"] = "Speak to Tami in Bastok Mines at (J-8) to begin quest.", ["|2"] = "She will give you the Tami's note.", ["|3"] = "Proceed to Zeruhn Mines and locate Zelman at (I-8).", ["|4"] = "Go to (H-5) in Bastok Mines (Bat's Lair Inn) and purchase a Meat Jerky from Griselda.", ["|5"] = "Trade the jerky to Tami for your reward of a Rabbit Mantle.", ["|6"] = "Proceed to Zeruhn Mines and locate Zelman at (I-8).", ["|7"] = "He will tell you that he is busy, and to tell Tami.", ["|8"] = "Return to Tami for your reward of 10 Gil."}},
    [38] = {s = {["|1"] = "Obtain a Bone Chip from the Auction House or by farming Skeleton type mobs.", ["|2"] = "Speak to Degenhard to begin quest.", ["|3"] = "Trade him the chip to complete quest."}},
    [39] = {s = {["|1"] = "Gerbaum asks you to exterminate the pests that roam inside Zeruhn Mines.", ["|2"] = "Collect 3 Zeruhn Soot either by killing the monsters in Zeruhn Mines, or by buying them off the auction house.", ["|3"] = "Trade them to Gerbaum for your reward."}},
    [40] = {s = {["|1"] = "Obtain 2 Darksteel Ores via the Auction House, Mog Garden, Mining, etc.", ["|2"] = "Speak to Mighty Fist on the first floor of the Metalworks (HP #2) to begin the quest.", ["|3"] = "Trade him the two ores to end the quest.", ["|4"] = "You may immediately repeat this quest."}},
    [41] = {s = {["|1"] = "Start the quest by talking to Foss.", ["|2"] = "Once you accept, obtain 5 Rusty Buckets by either fishing for them or buying them off auction houses or Kahah Hobichai in Al Zahbi.", ["|3"] = "Trade the 5 Rusty Buckets to him for your reward."}},
    [42] = {s = {["|1"] = "You may work on this quest only after you have obtained an Airship pass as its completion requires a trip on the airship.", ["|2"] = "If you fulfill all the prerequisites of the quest, then speak to Agapito to begin quest.", ["|3"] = "During a Full Moon at night time, board the San d'Oria-Jeuno airship.", ["|4"] = "Search for an abnormal ??? somewhere on the ship.", ["|5"] = "Touch the ??? to receive the Carrier pigeon letter.", ["|6"] = "Return to Agapito to complete the quest."}},
    [43] = {s = {["|2"] = "Speak with Carmelo inside the Steaming Sheep to receive the actual quest.", ["|3"] = "Travel to G-10 in Beaucedine Glacier (at the ice pond) and click on Mirror Pond which only appears during days without snow or clouds.", ["|4"] = "After the cutscene, return to Bastok and speak to Carmelo to complete quest"}},
    [45] = {s = {["|1"] = "Speak to Izabele to begin the quest.", ["|2"] = "Invite at least one other player to form a party of 2.", ["|3"] = "Together with your party, travel to North Gustaberg and locate the galka Hunting Bear at F-8 (near the waterfall).", ["|4"] = "Speak with Hunting Bear to complete the quest."}},
    [46] = {s = {["|1"] = "Talk to Yazan (H-6), who asks you to exterminate Sand Bats in Valkurm Dunes.", ["|2"] = "Once you have one, trade it to Yazan for your reward."}},
    [47] = {s = {["|1"] = "Speak to Gumbah to receive the key item Letter from Zeid.", ["|2"] = "Use the Chaosbringer to slay 100 more enemies.", ["|3"] = "Go to Gusgen Mines and trade the Chaosbringer to the ??? at (J-7) on Map 1 to receive your reward."}},
    [48] = {s = {["|1"] = "Speak to Paujean to begin the quest.", ["|2"] = "Obtain a Rampaging Horn and a Lumbering Horn:", ["|3"] = "Lumbering Horn is obtainable via the following means:", ["|4"] = "Rampaging Horn is obtainable via the following means:", ["|5"] = "Trade both items to Paujean to complete quest."}},
    [49] = {s = {["|1"] = "Speak with Virnage, located at (I-5) in the Bat's Lair Inn on the second level of Ore Street of Bastok Mines, to begin quest.", ["|2"] = "Travel to Garlaige Citadel and locate a ??? at (H-8) (First floor Map 1).", ["|3"] = "Touch the ??? to receive a Bucket of divine paint.", ["|4"] = "Return to Bastok and speak with Virnage.", ["|5"] = "Travel to Northern San d'Oria and speak with Eperdur at M-7 (Cathedral) to complete quest."}},
    [50] = {s = {["|1"] = "(optional) Talk to Valah Molkot.", ["|2"] = "She won't come out and say it at first, but she would like an Amaryllis.", ["|3"] = "Trade it to her to complete the quest."}},
    [51] = {s = {["|1"] = "Talk to Oggbi inside the Steaming Sheep Restaurant for a cutscene.", ["|2"] = "Get a Pickaxe from the Auction House or from any source.", ["|3"] = "Travel to Gusgen Mines.", ["|4"] = "Get to the 3rd map by taking the ramp down at (F-5) and trade a Pickaxe to the ??? at (G-7) to spawn Wandering Ghost.", ["|5"] = "Wandering Ghost drops a Miner's Pendant and the Pickaxe is still in your inventory.", ["|6"] = "Trade the Miner's Pendant to Oggbi and receive Beat Cesti."}},
    [52] = {s = {["|1"] = "Note: If you just finished Ghosts of the Past, then you must zone before beginning this quest", ["|2"] = "Talk to Oggbi inside the Steaming Sheep Restaurant for a cutscene.", ["|3"] = "Travel to Fei'Yin.", ["|4"] = "Travel to Davoi and look for the Hide Flap at (F-7)/(G-7).", ["|5"] = "When ready click the Hide Flap and pop Deloknok (PLD) and Bilopdop (MNK).", ["|6"] = "Go back and talk to Oggbi and receive your Temple Gaiters."}},
    [53] = {s = {["|1"] = "Talk to Ayame in the Metalworks at (K-7).", ["|2"] = "Travel to Castle Oztroja.", ["|3"] = "Head to the top floor where you have limited time to get past the gate before it closes.", ["|4"] = "Look for a torch with a ??? on it at (H-8).", ["|5"] = "He drops Xalmo Feather.", ["|6"] = "Trade the feather to Ayame for your Temple Hose."}},
    [54] = {s = {["|1"] = "Talk to Phara in Bastok Mines at (J-9).", ["|2"] = "Go to Davoi and click the Hide Flap at K-9/10.", ["|3"] = "Kill them then check the Hide Flap to receive the Sword grip material.", ["|4"] = "Speak to Phara then wait a game day (after clock rolls around past 00:00).", ["|5"] = "Speak to Phara again for Yasin's sword.", ["|6"] = "Speak to Naji outside the President's Office in Metalworks at (J-8) for a cutscene to finish the quest and receive your Razor Axe."}},
    [55] = {s = {["|1"] = "Talk to Phara in Bastok Mines at (J-9).", ["|2"] = "Talk to Deidogg (H-6) Bastok Mines twice.", ["|3"] = "Go Palborough Mines and work your way to the top floor.", ["|4"] = "Examine it to spawn Ni'Ghu Nestfender.", ["|5"] = "Return to Bastok and trade the Mottled Quadav Egg to Deidogg.", ["|6"] = "Go to Castle Oztroja and kill the Yagudo Parasite in the pond on the 3rd floor (H-9) for a Parasite Skin.", ["|7"] = "Return to Bastok again and trade the Parasite Skin to Deidogg.", ["|8"] = "Wait a game day (after clock rolls around past 00:00)."}},
    [56] = {s = {["|1"] = "You must wait until the next game day after completing The Talekeeper's Truth before you can activate this quest.", ["|2"] = "Speak to Deidogg in Bastok Mines.", ["|3"] = "Speak to Detzo in Bastok Mines (I-6), located in the alleyway around the corner from Deidogg.(Speak to him again if he mentions a Mythril", ["|4"] = "Obtain a Ginger Cookie and trade it to Deidogg.", ["|5"] = "Travel to Behemoth's Dominion.", ["|6"] = "Proceed to (K-9) in Behemoth's Dominion to find a ???.", ["|7"] = "Defeat the NMs, and zone out of Behemoth's Dominion (back into Qufim Island) to receive a cutscene and your reward."}},
    [57] = {s = {["|1"] = "Speak with Cid's Assistant Raibaht to start quest.", ["|2"] = "Speak with Mighty Fist in Metalworks (G-9) (lower level; inside Darksteel Forge) and you will receive a key item: Letter from the Darksteel", ["|3"] = "Travel to Windurst Waters and speak to Cochal-Monchal (F-8) (HP #1 - North Map - Optistery)", ["|4"] = "Obtain a Yagudo Cherry from either a vendor or the auction house.", ["|5"] = "Travel to Giddeus and trade the Yagudo Cherry to the ??? at H-14.", ["|6"] = "Defeat the NM and click on the ??? again.", ["|7"] = "(Optional) Return to Metalworks and speak with Mighty Fist again for additional dialogue.", ["|8"] = "Return to Raibaht and speak with him to complete quest."}},
    [58] = {s = {["|1"] = "Speak with Cid as a Dark Knight to begin quest.", ["|10"] = "Trade Gerwitz's Sword to the ??? at (H-10) and it will spawn Gerwitz's Soul.", ["|11"] = "Defeat Gerwitz's Soul then head for La Theine Plateau at (G-10) on the same map.", ["|2"] = "Obtain a Darksteel Ingot from the Auction House or Crafting.", ["|3"] = "Zone into Ordelle's Caves for a cutscene.", ["|4"] = "Trade the Darksteel Ingot to the ??? at (I-8) on map 1 to spawn Gerwitz's Axe (NM).", ["|5"] = "Defeat Gerwitz's Axe and it will drop Gerwitz's Axe.", ["|6"] = "Head South up the ramp (D on the wiki maps).", ["|7"] = "Trade Gerwitz's Axe to the ??? at (H-8) on map 3 to spawn Gerwitz's Sword (NM).", ["|8"] = "Defeat Gerwitz's Sword and it will drop Gerwitz's Sword.", ["|9"] = "Head South to enter a large square room."}},
    [59] = {s = {["|1"] = "Zone into Beadeaux from Pashhow Marshlands as a Dark Knight to receive a cutscene to start the quest.", ["|2"] = "Farm Topaz Quadav until you acquire a Quadav Mage Blood.", ["|3"] = "Enter Middle Delkfutt's Tower by either climbing up from Lower Delkfutt's Tower or climbing down from the Upper Delkfutt's Tower Home Point.", ["|4"] = "Use the teleporter at (J-6) on the 7th floor.", ["|5"] = "Trade the Quadav Mage Blood to the ??? to spawn Gerwitz's Scythe NM and two Scythe Victims.", ["|6"] = "Defeat all 3 mobs and stand on the teleporter to go back upstairs.", ["|7"] = "Upon taking the teleport back, you will receive a cutscene and your reward."}},
    [60] = {s = {["|1"] = "Talk to Kaede in Port Bastok at (J-5) - nearest to Home Point #1 (E) - in the north most house for a cutscene.", ["|2"] = "Talk to Kagetora at (F-6), inside the door to Warehouse 2.", ["|3"] = "Return to Kaede's house and speak with Ensetsu at (I-5) for a cutscene.", ["|4"] = "Travel to (K-8) within Korroloka Tunnel, Map 5.", ["|5"] = "Click on the ??? to spawn 3 Korroloka Leeches.", ["|6"] = "Once the leeches are defeated and after the bodies despawn, click on the ??? to receive the Strangely shaped coral.", ["|7"] = "Return to Ensetsu in Port Bastok at (I-5).", ["|8"] = "Travel to Norg and speak with Ryoma at (H-8), who will give you the Sealed dagger.", ["|9"] = "Return to Ensetsu to complete the quest."}},
    [61] = {s = {["|1"] = "Speak with Juroro to obtain the quest.", ["|2"] = "Travel to Eastern Altepa Desert and look for the entrance to Quicksand Caves at (J-7) (where the level 30+ beetle/antica camp is).", ["|3"] = "Defeat Titan Prime and you will receive Whisper of tremors", ["|4"] = "Return to Juroro with the whisper and she will provide several reward options including the ability to summon Titan (Avatar)."}},
    [62] = {s = {["|1"] = "Zone after completing Love and Ice", ["|2"] = "Speak with Carmelo to begin quest", ["|3"] = "Travel to the following locations and procure 3 necessary items from Treasure Chests:", ["|7"] = "Return to Bastok and speak with Carmelo with all 3 key items in possesion.", ["|8"] = "After the conversation, zone out, then return to him and speak with him one last time to complete quest."}},
    [63] = {s = {["|1"] = "Zone after completing A Test of True Love", ["|2"] = "Speak with Carmelo to begin quest and receive the key item: \"Chanson de Liberte\"", ["|3"] = "Travel to H-8 of The Sanctuary of Zi'Tah to locate a ??? (middle of the pos)", ["|4"] = "Touch the ??? between 16:00-18:00 in-game time to complete quest."}},
    [64] = {s = {["|1"] = "Speak to Zacc (G-9) who is standing next to Enu (G-9).", ["|2"] = "Speak with Malene (I-5), more popularly known as the Steam Clock/Bubbly Bernie quest giver.", ["|3"] = "Return to the fountain and speak with Enu.", ["|4"] = "Acquire a Hatchet from the Auction House, NPC stores, or crafting.", ["|5"] = "Travel to Yuhtunga Jungle and locate a Logging Point.", ["|6"] = "Return to Enu and trade her the star on a clear starry night (Clear weather, with stars visible in the sky) to complete the quest."}},
    [65] = {s = {["|1"] = "Talk to Raifa (D-6) in the Steaming Sheep Restaurant in Port Bastok.", ["|2"] = "Head to Gusgen Mines and talk to Degga (H-9).", ["|3"] = "Head to (H-6) to find a ???.", ["|4"] = "Clicking the ??? will spawn two Pudding NMs.", ["|5"] = "Click the ??? after the NMs are defeated to receive Indigested ore.", ["|6"] = "Return to Raifa in Port Bastok to receive your reward."}},
    [66] = {s = {["|1"] = "You cannot start this quest if you have another Weapon Skill Quest active.", ["|2"] = "Speaking with Iron Eater will grant you the key item Weapon training guide as well as the Axe of Trials.", ["|6"] = "Trade the Axe of Trials back to Iron Eater.", ["|7"] = "This fight is against Greenman, a treant.", ["|8"] = "Go back and speak with Iron Eater to receive your reward."}},
    [67] = {s = {["|1"] = "Speaking with Cid will grant you the Weapon training guide as well as the Gun of Trials.", ["|2"] = "You will need to break the latent on the Gun of Trials before completing the rest of the Quest.", ["|5"] = "Trade the Gun of Trials back to Cid.", ["|6"] = "You will be instructed to travel to The Boyahda Tree.", ["|7"] = "This fight is against Beet Leafhopper, a Fly.", ["|8"] = "Once you kill it, re-examine the ??? to receive the Annals of Truth.", ["|9"] = "Go back and speak with Cid to receive your reward."}},
    [68] = {s = {["|1"] = "You cannot start this quest if you have another Weapon Skill Quest active.", ["|10"] = "Go back and speak with Gumbah to receive your reward.", ["|2"] = "Speaking with Gumbah will grant you the key item Weapon training guide as well as the Sword of Trials.", ["|6"] = "Trade the Sword of Trials back to Gumbah.", ["|7"] = "Next, travel to the oasis in Western Altepa Desert at (E-9).", ["|8"] = "Examine the ??? on the south side of the oasis to spawn the NM Maharaja, a tiger.", ["|9"] = "Re-examine the ??? after winning to receive the key item Annals of Truth."}},
    [69] = {s = {["|1"] = "You cannot start this quest if you have another Weapon Skill Quest active.", ["|2"] = "Speaking with Oggbi will grant you the key item Weapon training guide as well as the Knuckles of Trials.", ["|6"] = "Trade the Knuckles of Trials back to Oggbi.", ["|7"] = "Unity NPC warp 122 is available to get you close within Bostaunieux Oubliette well after the drop.", ["|8"] = "This fight is against Bodach, a skeleton.", ["|9"] = "Go back and speak with Oggbi to receive your reward."}},
    [70] = {s = {["|11"] = "Escort her to the 'end' point, and she will present you with the Completion certificate.", ["|12"] = "Return to Trilok to complete quest.", ["|6"] = "Speak with Trilok to begin quest."}},
    [72] = {s = {["|1"] = "Speak with Ferrol at Port Bastok (I-8) to begin quest and obtain a Mini Tuning Fork of Earth.", ["|4"] = "Defeat Titan Prime to complete quest."}},
    [73] = {s = {["|1"] = "Change your main job to Ninja (it must be level 20 or above) and speak to Romualdo at (K-9) in the southern Cannonry to begin quest.", ["|3"] = "Travel to Palborough Mines and open a Treasure Chest to receive the Diary of Mukunda", ["|4"] = "Return to Bastok to speak with Kagetora in Port Bastok at (F-6).", ["|5"] = "After that speak with Ayame again.", ["|6"] = "Finally, speak with Alois in the conference room of the President's Office at Metalworks (J-8) to complete the quest."}},
    [74] = {s = {["|1"] = "Speak to Brygid on any job while wearing any 1 to 5 pieces of Artifact Armor to begin the quest.", ["|2"] = "She will request one Body and one Legs armor items from the Armor requests table below.", ["|3"] = "When you return to her wearing both the requested pieces of armor, she will offer 13 different kinds of level 50 body armor from the", ["|4"] = "When you select the body armor you desire, she will require you to trade her a corresponding rare/ex Subligar which drops from Fomors in", ["|5"] = "You can repeat this quest as many times as you want (to get any piece of armor you desire)."}},
    [75] = {s = {["|1"] = "Talk to Ayame for a starting cut-scene, agree twice to start the quest.", ["|2"] = "Go to Port Bastok and talk with Ravorara (E-7) outside the Steaming Sheep Restaurant for a cutscene.", ["|3"] = "Go to Oldton Movalpolos and talk to Brakobrik (K-10).", ["|4"] = "Kill Ancient Bombs in Oldton Movalpolos to get Hoary Bomb Ash.", ["|5"] = "Trade between 1 to 4 Hoary Bomb Ash to Brakobrik at (K-11) to receive 4 different key items.", ["|7"] = "Return to Oldton Movalpolos and trade the final/11th ash to Brakobrik at (K-11), but choose \"No Thanks\" when he offers to give you", ["|8"] = "Return to Port Bastok and talk with Ravorara for another cutscene.", ["|9"] = "Go to Bastok Mines and talk with Pavvke in his residence on the lower level (I-7) for a cutscene, completing the quest and receiving your"}},
    [76] = {s = {["|1"] = "Speak to Marin and accept the quest.", ["|27"] = "After Ken despawns, Marin will appear at the exit.", ["|28"] = "Return to Bastok Markets and speak to Marin again to finish the quest."}},
    [77] = {s = {["|1"] = "Talk to Ayame for a cut-scene that starts the quest.", ["|2"] = "Go to Bastok Mines and talk with Virnage at (I-5) for a cut-scene.", ["|3"] = "Go to Oldton Movalpolos and talk with Rakorok at (K-10).", ["|4"] = "After defeating Bugallug, talk with Rakorok for a cut-scene where you will lose the Dawn talisman.", ["|5"] = "Return to Bastok Mines and talk with Virnage to complete the quest and receive your reward."}},
    [78] = {s = {["|1"] = "Talk to Ayame for a cut-scene that starts the quest.", ["|11"] = "Return to Metalworks and talk with Ayame for the Bowyer Ring reward, and to end the quest.", ["|12"] = "Optional followup: talk to the Tarutaru Ravorara from the earlier quests, to sell the Pungent providence pot for 1000 gil and receive a", ["|2"] = "Go to Oldton Movalpolos for a cutscene upon zoning.", ["|4"] = "Go to Lower Jeuno and trade the Misareaux Garlic to Muckvix (located at H-10 in Goblins' Goblet, through Muckvix's Junk Shop.) After a", ["|5"] = "Go to Kazham and talk with Magriffon, located at (I-7) in Celodehki's Bed & Breakfast.", ["|6"] = "Return to Lower Jeuno and talk with Muckvix for a cutscene where you deliver the key items and receive the Pungent providence pot key item", ["|7"] = "Return to Oldton Movalpolos for a short cutscene.", ["|8"] = "If you are in a party, each one must trade an Ahriman Tears to Tarnotik to be teleported to Mine Shaft #2716 BCNM zone OR use the Home"}},
    [79] = {s = {["|1"] = "Speak with Raibaht in Cid's lab to begin quest.", ["|2"] = "Travel to Carpenters' Landing to obtain a Garhada Teak Lumber.", ["|3"] = "Return to Raibaht and trade him the lumber to complete quest."}},
    [80] = {s = {["|1"] = "If you have just completed Teak Me to the Stars, you must zone before starting this quest.", ["|2"] = "Speak with Raibaht to begin quest.", ["|3"] = "Travel to Lower Delkfutt's Tower and proceed to the basement.", ["|4"] = "Travel to (I-6) of the basement map and touch the Cermet Door to pop 3 NMs: Orna (the boss) and 2 Fomorian Spear.", ["|5"] = "Defeat Orna (which will make the other two depop) and touch the Cermet Door again.", ["|6"] = "Travel to Lower Jeuno and inspect the Street Lamp targets until you find a Hyper altimeter.", ["|7"] = "Return to Bastok and speak with Raibaht to complete the quest."}},
    [81] = {s = {["|1"] = "Obtain an Ordrynite", ["|7"] = "Trade it to Raibaht to complete quest"}},
    [82] = {s = {["|1"] = "Speak to Ghebi Damomohe in Lower Jeuno (I-7) when you are on (or finished with) the mission More Questions than Answers to begin the quest.", ["|2"] = "In Pso'Xja fight the following monsters until you acquire the three chips.", ["|3"] = "Trade all three chips to Cid in Bastok Metalworks."}},
    [83] = {s = {["|1"] = "Speak to Salim to start the quest.", ["|15"] = "Once all switches have been deactivated, return to the ??? in the Temple of the Goddess for a cutscene and your reward."}},
    [84] = {s = {["|1"] = "Speak with Alib-Mufalib to recieve a Blue Sentinel badge and begin the quest.", ["|3"] = "Once you have spoken to all 20 people, return to Alib-Mufalib.", ["|4"] = "After joining Salaheem's Sentinels, speak to Naja Salaheem with the invitation card, and she will reward you with Imperial currency.", ["|5"] = "After joining Salaheem's Sentinels, Alib-Mufalib will offer to teleport you to Aht Urhgan Whitegate."}},
    [85] = {s = {["|1"] = "Shamarhaan is the Puppetmaster standing near the Fountain in Bastok Markets.", ["|2"] = "Farm Trolls for the testimony.", ["|3"] = "Trade to Shamarhaan to initiate the Navukgo Execution Chamber BC (you will be warped there), where just like the Maat fight, you'll have to"}},
    [86] = {s = {["|1"] = "Speak to Ferghus for a cutscene.", ["|2"] = "Speak to Leonhardt for another cutscene.", ["|3"] = "Go to Bastok Markets (S) and speak to Raginmund near Harmodio's Music Shop (L-10).", ["|4"] = "Obtain a Red Oven Mitt from Copper Quadav and Onyx Quadav in Grauberg (S) or North Gustaberg (S).", ["|5"] = "Trade the Red Oven Mitt to Leonhardt for a brief cutscene.", ["|6"] = "Speak to Umberto in Bastok Markets near Harmodio's Music Shop (L-10) for a cutscene and your reward."}},
    [87] = {s = {["|1"] = "Speak to Offa to begin quest.", ["|12"] = "Whichever way you decided to complete the previous section, once you have obtained the Rolanberry he gives, travel to Bastok Markets (S)"}},
    [88] = {s = {["|1"] = "Speak to Titus on the second floor of the Alchemy Guild in Bastok Mines for a cutscene that begins the quest.", ["|2"] = "Travel to Grauberg (S) and find the Riverbed at (F-13).", ["|3"] = "When you examine the Riverbed, you will receive the following options:", ["|4"] = "When you select one, you will then receive the following options:", ["|5"] = "To extract gold, you must wash away as much sediment as possible without washing away any gold dust.", ["|6"] = "Choose that and you will gain a random amount of gold dust grains (generally between 3 to 11).", ["|7"] = "Speak to Titus again for a cutscene to receive your reward."}},
    [90] = {s = {["|3"] = "Synergize the stones into Astral Matter in a Synergy Furnace, then trade Selliste the result for your reward."}},
    [91] = {s = {["|3"] = "Choose a type from the list and you will be given three of that choice and the quest will be completed."}},
    [92] = {s = {["|1"] = "Speak to Clarion Star in Port Bastok HP #1 at (K-7), he will give you the Blue institute card.", ["|2"] = "Head to Metalworks HP #1 (J-8) and speak to Naji."}},
}
